-- =============================================================================
-- Migration V20: Roadmap Page Tables & Data Seeding
-- Tables: categories, steps, topics, resources, user_progress
-- =============================================================================

CREATE TABLE IF NOT EXISTS categories (
    id INTEGER PRIMARY KEY,
    title VARCHAR(255) NOT NULL
);

CREATE TABLE IF NOT EXISTS steps (
    id INTEGER PRIMARY KEY,
    category_id INTEGER NOT NULL REFERENCES categories(id) ON DELETE CASCADE,
    title VARCHAR(255) NOT NULL,
    "order" INTEGER NOT NULL
);

CREATE INDEX IF NOT EXISTS idx_steps_category ON steps(category_id);

CREATE TABLE IF NOT EXISTS topics (
    id VARCHAR(50) PRIMARY KEY,
    step_id INTEGER NOT NULL REFERENCES steps(id) ON DELETE CASCADE,
    name VARCHAR(255) NOT NULL,
    points JSONB NOT NULL DEFAULT '[]'::jsonb,
    "order" INTEGER NOT NULL
);

CREATE INDEX IF NOT EXISTS idx_topics_step ON topics(step_id);

CREATE TABLE IF NOT EXISTS resources (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    topic_id VARCHAR(50) NOT NULL REFERENCES topics(id) ON DELETE CASCADE,
    type VARCHAR(50) NOT NULL,
    title VARCHAR(500) NOT NULL,
    url VARCHAR(1000) NOT NULL,
    CONSTRAINT uk_resources_topic_url UNIQUE (topic_id, url)
);

CREATE INDEX IF NOT EXISTS idx_resources_topic_type ON resources(topic_id, type);

CREATE TABLE IF NOT EXISTS user_progress (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    topic_key VARCHAR(50) NOT NULL REFERENCES topics(id) ON DELETE CASCADE,
    completed_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    CONSTRAINT uk_user_progress_user_topic UNIQUE (user_id, topic_key)
);

CREATE INDEX IF NOT EXISTS idx_user_progress_user ON user_progress(user_id);

-- Seed Categories
ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title;

-- Seed Steps
ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, "order" = EXCLUDED."order";

-- Seed Topics
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, points = EXCLUDED.points, "order" = EXCLUDED."order";

-- Ensure UUID defaults exist even if tables were pre-created by Hibernate ddl-auto=update
ALTER TABLE resources ALTER COLUMN id SET DEFAULT gen_random_uuid();
ALTER TABLE user_progress ALTER COLUMN id SET DEFAULT gen_random_uuid();

-- Seed Resources
ON CONFLICT (topic_id, url) DO UPDATE SET type = EXCLUDED.type, title = EXCLUDED.title;

DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1
        FROM information_schema.table_constraints
        WHERE table_schema = 'public'
          AND table_name = 'resources'
          AND constraint_name = 'uk_resources_topic_url'
    ) THEN
        ALTER TABLE resources ADD CONSTRAINT uk_resources_topic_url UNIQUE (topic_id, url);
    END IF;
END $$;